node -e "
const fs = require('fs');
const buffer = fs.readFileSync('/app/a.out');
const shOff = 13976;
const shNum = 31;
const shEntSize = 64;
const shNameStrIdx = 30;

// Read section headers
const sections = [];
for (let i = 0; i < shNum; i++) {
    const offset = shOff + i * shEntSize;
    const sh_name = buffer.readUInt32LE(offset);
    const sh_type = buffer.readUInt32LE(offset + 4);
    const sh_addr = buffer.readUInt32LE(offset + 16) | (buffer.readUInt32LE(offset + 20) << 32);
    const sh_offset = buffer.readUInt32LE(offset + 24) | (buffer.readUInt32LE(offset + 28) << 32);
    const sh_size = buffer.readUInt32LE(offset + 32) | (buffer.readUInt32LE(offset + 36) << 32);

    sections.push({ name: sh_name, type: sh_type, addr: sh_addr, offset: sh_offset, size: sh_size });
}

console.log('shstrtab section:', shNameStrIdx);
console.log('shstrtab offset:', sections[shNameStrIdx].offset);
console.log('shstrtab size:', sections[shNameStrIdx].size);

const nameBuffer = buffer.slice(sections[shNameStrIdx].offset, sections[shNameStrIdx].offset + sections[shNameStrIdx].size);
console.log('Name buffer length:', nameBuffer.length);
console.log('First 50 bytes:', Array.from(nameBuffer.slice(0, 50)).join(','));
"

